import React, { useState } from "react";
import AdminProductDetails from "../AdminProductDetails/AdminProductDetails";
import ProductList from "../ProductList/AdminProductList";
import AdminOrderList from "../Orders/AdminOrderList";
import OrderDetails from "../Orders/OrderDetails";
import { getBaseURL } from "../apiConfig";
import axios from "axios";
import "./AdminContainer.scss";

const AdminContainer = (props) => {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [showProductList, setShowProductList] = useState(true);
  const [cart, setCart] = useState([]); // État pour le panier

  const handleProductDetails = (product) => {
    if (props.isAdmin === 1) {
      setSelectedProduct(product);
    } else {
      alert("Access denied: Only admins can view product details.");
    }
  };

  const addToCart = (product) => {
    // Vérifiez si le produit est déjà dans le panier
    const existingProduct = cart.find((item) => item.productId === product.productId);

    if (existingProduct) {
      // Vérifiez si le stock permet d'ajouter une unité supplémentaire
      if (existingProduct.quantity + 1 > product.stock) {
        alert("Not enough stock available!");
        return;
      }
      // Mettez à jour la quantité dans le panier
      setCart((prevCart) =>
        prevCart.map((item) =>
          item.productId === product.productId
            ? { ...item, quantity: item.quantity + 1 }
            : item
        )
      );
    } else {
      // Ajoutez le produit au panier avec une quantité initiale de 1
      if (product.stock > 0) {
        setCart((prevCart) => [...prevCart, { ...product, quantity: 1 }]);
      } else {
        alert("Product is out of stock!");
      }
    }
  };

  const removeFromCart = (productId) => {
    // Retirez le produit du panier
    setCart((prevCart) => prevCart.filter((item) => item.productId !== productId));
  };

  const checkout = () => {
    // Simulez le passage à la caisse (ou envoyez les données au backend)
    alert("Checkout successful!");
    console.log("Cart items:", cart);
    setCart([]); // Réinitialisez le panier après le passage à la caisse
  };

  return (
    <div className="admin-container">
      {selectedProduct ? (
        <div className="details-container">
          <AdminProductDetails
            productId={selectedProduct.productId}
            onBackClick={() => setSelectedProduct(null)}
          />
        </div>
      ) : (
        <>
          <div>
            {showProductList ? (
              <div className="product-list-container">
                <button onClick={() => setShowProductList(false)}>
                  Get Order List
                </button>
                <ProductList
                  isAdmin={props.isAdmin}
                  handleProductDetails={handleProductDetails}
                  addToCart={addToCart} // Passez la fonction d'ajout au panier
                />
                {/* Affichez le panier */}
                <div className="cart-container">
                  <h2>Cart</h2>
                  {cart.length === 0 ? (
                    <p>Your cart is empty.</p>
                  ) : (
                    <ul>
                      {cart.map((item) => (
                        <li key={item.productId}>
                          {item.name} - {item.quantity} pcs
                          <button onClick={() => removeFromCart(item.productId)}>
                            Remove
                          </button>
                        </li>
                      ))}
                    </ul>
                  )}
                  {cart.length > 0 && (
                    <button onClick={checkout}>Checkout</button>
                  )}
                </div>
              </div>
            ) : (
              <div className="order-list-container">
                {selectedOrder ? (
                  <div className="details-container">
                    <OrderDetails
                      orderId={selectedOrder.orderId}
                      onBackClick={() => setSelectedOrder(null)}
                    />
                  </div>
                ) : (
                  <div>
                    <button onClick={() => setShowProductList(true)}>
                      Get Product List
                    </button>
                    <AdminOrderList handleOrderDetails={setSelectedOrder} />
                  </div>
                )}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default AdminContainer;
